api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Hackathon Banner Styles */
.hackathon-banner {
  //   background: url("/x_1097288_hacktaho.hackathon-banner.png") center/cover
  //     no-repeat;
  min-height: 540px;
  display: flex;
  align-items: center;
  position: relative;
  padding: 0;
}

.hackathon-banner__content {
  display: flex;
  justify-content: space-between;
  align-items: stretch;
  //   width: 90%;
  //   margin: 0 auto;
  max-width: 1600px;
  padding: 48px 0;
}

.hackathon-banner__text {
  background: rgba(255, 255, 255, 0.95);
  padding: 48px 40px 40px 48px;
  border-radius: 0 32px 32px 0;
  max-width: 520px;
  min-width: 340px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.hackathon-banner__subtitle {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  margin-bottom: 18px;
  color: #222;
  text-transform: uppercase;
}

.hackathon-banner__title {
  font-size: 2.9rem;
  font-weight: 900;
  line-height: 1.1;
  margin-bottom: 24px;
  color: #181818;
}

.hackathon-banner__desc {
  font-size: 1.15rem;
  color: #333;
  margin-bottom: 32px;
  line-height: 1.5;
}

.hackathon-banner__cta {
  background: #d32f2f; /* red */
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 14px 38px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s;
}
.hackathon-banner__cta:hover {
  background: #b71c1c; /* darker red on hover */
}

.hackathon-banner__images {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-end;
  gap: 24px;
  //   margin-left: 48px;
}

.hackathon-banner__main-img,
.hackathon-banner__secondary-img {
  width: 480px;
  height: 320px;
  object-fit: cover;
  border-radius: 12px;
  box-shadow: 0 6px 32px rgba(0, 0, 0, 0.18);
  background: #eee;
}

@media (max-width: 1100px) {
  .hackathon-banner__content {
    flex-direction: column;
    align-items: center;
    padding: 32px 0;
  }
  .hackathon-banner__images {
    margin-left: 0;
    margin-top: 32px;
    flex-direction: row;
    gap: 24px;
  }
}

@media (max-width: 700px) {
  .hackathon-banner__content {
    width: 100%;
    padding: 16px 0;
  }
  .hackathon-banner__text {
    padding: 24px 12px 20px 12px;
    max-width: 100%;
    min-width: 0;
    border-radius: 0 0 24px 24px;
  }
  .hackathon-banner__main-img,
  .hackathon-banner__secondary-img {
    width: 100vw;
    max-width: 98vw;
    height: 180px;
  }
  .hackathon-banner__images {
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }
}
